test('invoiceTotals with multiple discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 5, vatRate: 21 },
      { qty: 5, unitPrice: 9500, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const discount1 = Math.round(95000 * 0.05);
  const discount2 = Math.round(47500 * 0.1);
  assert.equal(totals.discount, discount1 + discount2);
});

input.new_string:
test('invoiceTotals with multiple discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 5, vatRate: 21 },
      { qty: 5, unitPrice: 9500, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const discount1 = Math.round(95000 * 0.05);
  const discount2 = Math.round(47500 * 0.1);
  assert.equal(totals.discount, discount1 + discount2);
});

test('invoiceTotals applies bulk discount for 10+ units', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const lineAmount = 10000;
  const bulkDiscount = Math.round(lineAmount * 0.025);
  assert.equal(totals.discount, bulkDiscount);
});

test('invoiceTotals does not apply bulk discount for 9 units', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.discount, 0);
});

test('invoiceTotals applies bulk discount after line discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const lineAmount = 10000;
  const firstDiscount = Math.round(lineAmount * 0.1);
  const afterFirst = lineAmount - firstDiscount;
  const bulkDiscount = Math.round(afterFirst * 0.025);
  const totalDiscount = firstDiscount + bulkDiscount;
  assert.equal(totals.discount, totalDiscount);
});

test('invoiceTotals calculates VAT after bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const lineAmount = 10000;
  const bulkDiscount = Math.round(lineAmount * 0.025);
  const afterBulkDiscount = lineAmount - bulkDiscount;
  const expectedVat = Math.round(afterBulkDiscount * 0.21);
  assert.equal(totals.vat, expectedVat);
});

test('invoiceTotals with bulk discount and high line discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 50, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const lineAmount = 100000;
  const firstDiscount = Math.round(lineAmount * 0.5);
  const afterFirst = lineAmount - firstDiscount;
  const bulkDiscount = Math.round(afterFirst * 0.025);
  const totalDiscount = firstDiscount + bulkDiscount;
  assert.equal(totals.discount, totalDiscount);
});

test('invoiceTotals bulk discount applies independently to each line', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const bulkDiscount1 = Math.round(10000 * 0.025);
  assert.equal(totals.discount, bulkDiscount1);
});

test('invoiceTotals with multiple lines all bulk discount eligible', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 15, unitPrice: 2000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const bulkDiscount1 = Math.round(10000 * 0.025);
  const bulkDiscount2 = Math.round(30000 * 0.025);
  assert.equal(totals.discount, bulkDiscount1 + bulkDiscount2);
});

test('invoiceTotals bulk discount with zero discountPercent', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedBulkDiscount = Math.round(10000 * 0.025);
  assert.equal(totals.discount, expectedBulkDiscount);
});

test('invoiceTotals bulk discount at threshold (exactly 10)', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedBulkDiscount = Math.round(1000 * 0.025);
  assert.equal(totals.discount, expectedBulkDiscount);
});

test('invoiceTotals bulk discount just below threshold (9 units)', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 100, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.discount, 0);
});

